import React, { useEffect, useState } from "react";
import axios from "../utils/axios";
import BudgetCard from "../components/BudgetCard";
import { useNavigate } from "react-router-dom";
import Modal from "../components/Modal";
import CreateBudgetForm from "../components/CreateBudgetForm";
import toast from "react-hot-toast";

const Budgets = () => {
  const [budgets, setBudgets] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1);
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());

  const navigate = useNavigate();

  const fetchBudgets = async () => {
    try {
      const email = localStorage.getItem("email");
      const response = await axios.get("/api/budgets", {
        headers: { email },
      });
      setBudgets(Array.isArray(response.data) ? response.data : []);
    } catch (error) {
      console.error("Failed to fetch budgets", error);
      toast.error("Failed to load budgets");
    }
  };

  useEffect(() => {
    fetchBudgets();
  }, []);

  const filteredBudgets = budgets.map((budget) => {
    const filteredExpenses = (budget.expenses || []).filter((expense) => {
      const date = new Date(expense.date);
      return (
        date.getMonth() + 1 === selectedMonth &&
        date.getFullYear() === selectedYear
      );
    });
    return { ...budget, filteredExpenses };
  });

  return (
    <div className="ml-64 p-6">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-4">
          <h1 className="text-2xl font-bold">My Budgets –</h1>
          <select
            value={selectedMonth}
            onChange={(e) => setSelectedMonth(Number(e.target.value))}
            className="border px-2 py-1 rounded"
          >
            {Array.from({ length: 12 }, (_, i) => (
              <option key={i + 1} value={i + 1}>
                {new Date(0, i).toLocaleString("default", { month: "long" })}
              </option>
            ))}
          </select>
          <select
            value={selectedYear}
            onChange={(e) => setSelectedYear(Number(e.target.value))}
            className="border px-2 py-1 rounded"
          >
            {[2024, 2025, 2026].map((year) => (
              <option key={year} value={year}>{year}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
        {/* Create New Budget */}
        <div
          className="border-2 border-dashed border-gray-300 rounded-lg p-6 cursor-pointer hover:bg-gray-100 flex flex-col items-center justify-center"
          onClick={() => setIsModalOpen(true)}
        >
          <span className="text-3xl">➕</span>
          <p className="font-medium mt-2">Create New Budget</p>
        </div>

        {filteredBudgets.map((budget) => {
          const totalSpent = budget.filteredExpenses.reduce(
            (sum, expense) => sum + (expense.amount || 0),
            0
          );
          const itemCount = budget.filteredExpenses.length;

          return (
            <div
              key={budget.id}
              onClick={() =>
                navigate(`/budgets/${budget.id}/expenses`, {
                  state: { budget, selectedMonth, selectedYear },
                })
              }
              className="cursor-pointer"
            >
              <BudgetCard
                icon={budget.icon}
                name={budget.name}
                amount={budget.amount}
                spent={totalSpent}
                itemsCount={itemCount}
              />
            </div>
          );
        })}
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}>
        <CreateBudgetForm
          onSuccess={() => {
            setIsModalOpen(false);
            fetchBudgets();
          }}
        />
      </Modal>
    </div>
  );
};

export default Budgets;
